// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;
    function setUp() public { c = new PhiNFT1155(); }

    function testFuzz_property(address actor1, address actor2) public {
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != actor2);

        vm.prank(actor1);
        address observed1 = c.owner();
        vm.prank(actor2);
        address observed2 = c.owner();

        // General rule: owner() is caller-independent — every caller observes the same owner value.
        assertTrue(observed1 == observed2);
    }
}
